INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.67.2',
  '2026-08-04',
  'Фикс: смена картинки фона сбрасывала настройки карточек',
  E'Исправлено: после выбора другой картинки фона непрозрачность и размытие карточек возвращались к обычным. По той же причине могли сбрасываться цвет текста и цвет фона, заданные в своей теме.',
  E'Причина: модуль фона остался с прежних времён и при каждом применении фона выставлял --card-alpha/--card-blur, --text-color и --bg-color из ответа /settings/background. С v2.67 это токены темы, которые ставит applyTokens, — то есть ответ старой ручки затирал тему. В ответе после миграции 0078 там лежат значения по умолчанию (card_opacity 100, цвета пустые), поэтому «стекло» карточек и слетало.\n\nПочинено: из shared/background.ts убраны applyCardStyle / applyTextColors / applyBgColors вместе с их применением и кэшированием; модуль отвечает теперь только за саму картинку и её эффекты (размытие, затемнение, размещение). Наблюдатель за сменой data-theme там тоже больше не нужен — цвета приходят из токенов.\n\nВторая половина фикса на сервере: store.SetBackground писал ВСЕ колонки оформления, поэтому сохранение фона затирало перенесённые миграцией text_color_*, bg_color_* и card_* значениями по умолчанию. Теперь запрос трогает только bg_kind/bg_value/bg_position/bg_blur/bg_dim.\n\nПроверено в браузере: непрозрачность 45% и размытие 10px переживают смену картинки фона и полную перезагрузку страницы.'
);
